const raw = $input.first().json;

// Body: Twilio directo, Twilio via proxy Vercel (body anidado), chat hook
const bodyRaw = raw.Body || raw.body?.Body || raw.messages?.[0]?.text?.body || raw.text || (typeof raw.body === 'string' ? raw.body : null) || raw.chatInput || raw.message || '';
const body = String(bodyRaw).trim();

if (!body) throw new Error('Mensaje vacío');

// From: Twilio directo o via proxy Vercel (body anidado)
const rawFrom = raw.From || raw.body?.From || raw.messages?.[0]?.from || raw.from || raw.sender || '';
const is_twilio = !!rawFrom;

let remitente = '';

if (rawFrom) {
  remitente = String(rawFrom)
    .replace(/^whatsapp:\+?/i, '')
    .replace(/[^0-9]/g, '')
    .replace(/^57/, '')
    .slice(-10);
}

// Si no hay remitente (chat hook u otros), extraer celular del cuerpo
if (!remitente || remitente.length !== 10) {
  const celularLine = body.match(/celular\s*[:\-]?\s*(\+?[\d\s]{10,15})/i);
  if (celularLine) {
    const digits = celularLine[1].replace(/\D/g, '').replace(/^57/, '').slice(-10);
    if (/^3\d{9}$/.test(digits)) remitente = digits;
  }
}
if (!remitente || remitente.length !== 10) {
  const match = body.match(/\b(3[0-9]{9})\b/);
  if (match) remitente = match[1];
}

if (!remitente || remitente.length !== 10) {
  throw new Error('No se pudo extraer numero de remitente');
}

return [{ json: { remitente, body, raw_payload: raw, is_twilio } }];

const response = $input.first().json;
// Soporta AI Agent node (response.output) y OpenAI HTTP API (response.choices[0].message.content)
const content = response.output || response.choices?.[0]?.message?.content || '';
let parsed;
try {
  // Limpiar posibles backticks o whitespace
  const cleaned = content.replace(/```json\n?/g, '').replace(/```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error('La IA no devolvió JSON válido: ' + content.substring(0, 200));
}

// Validar celular
let celular = String(parsed.celular || '').replace(/[\s\-\(\)]/g, '').replace(/^\+?57/, '').replace(/^0/, '').slice(-10);
if (!/^3\d{9}$/.test(celular)) {
  throw new Error('No se encontró un celular colombiano válido. IA extrajo: ' + (parsed.celular || 'nada'));
}

// Normalizar monto
let monto_total = null;
if (parsed.monto_total !== null && parsed.monto_total !== undefined) {
  monto_total = typeof parsed.monto_total === 'number' ? parsed.monto_total : parseFloat(String(parsed.monto_total).replace(/[^0-9.]/g, ''));
  if (isNaN(monto_total)) monto_total = null;
}

const body = $('Extraer Remitente y Body').first().json.body;

return [{ json: {
  nombre_cliente: String(parsed.nombre_cliente || 'Cliente Domicilio').trim(),
  celular,
  direccion: parsed.direccion || null,
  metodo_pago: parsed.metodo_pago || null,
  monto_total,
  ciudad: parsed.ciudad || 'Envigado',
  raw_message: body
} }];
